// The generated files' text, from given facts: each says it is generated in its first line and holds what it was given.
import { strict as assert } from "node:assert";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import * as Arr from "effect/Array";
import * as Option from "effect/Option";
import * as Rec from "effect/Record";
import * as Str from "effect/String";
import {
  generatedFrom,
  header,
  renderAbi,
  renderMap,
  renderSeeded,
  renderSite,
  renderSitePackage,
  saysOf,
  type Seeded,
} from "../src/render.ts";
import { OUTPUTS } from "../src/sources.ts";

const literal = (value: unknown): string => JSON.stringify(value, null, 2);
const firstLine = (text: string): string => Arr.headNonEmpty(Str.split(text, "\n"));

const seeded: Seeded = {
  chainId: 1,
  companiesHouse: "0x01",
  companiesHouseRoles: "0x02",
  createCall: "0x03",
  tiers: [{ tier: "t", namespace: "n", companyNamespace: "c", member: "0x04" }],
  contracts: { Payments: "0x05" },
  installer: { hats: "0x06" },
  head: { number: 7, timestamp: 8 },
  firstAccount: { address: "0x09", nonce: 10, nextContract: "0x0b" },
};

test("every generated file says so in its first line, naming what it is generated from", () => {
  for (const text of [
    renderAbi([], literal),
    renderSeeded(seeded, literal),
    renderSite({ WALLET_ADDRESS_FIELD: "w", DAILY_JOB: "d", DAILY_JOB_TYPE: "t", SAFE_ACCOUNT_PREFIX: "p" }, literal),
    renderSitePackage(),
  ])
    assert.match(firstLine(text), /^(\/\/|#) Generated by `pnpm generate` from .+\. Never edit it/);
});

test("the ABI module exports each ABI as a constant, in order", () => {
  const text = renderAbi(
    [
      { name: "A", abi: [{ type: "event", name: "E" }] },
      { name: "B", abi: [] },
    ],
    literal,
  );
  const at = (part: string) => Option.getOrElse(Str.indexOf(part)(text), () => -1);
  assert.ok(at("export const A = [") >= 0 && at("export const A = [") < at("export const B = []"));
  assert.match(text, /"name": "E"/);
});

test("the seeded table holds every fact it was given", () => {
  const text = renderSeeded(seeded, literal);
  for (const fact of [
    "chainId = 1",
    '"0x01"',
    '"0x02"',
    '"0x03"',
    '"Payments": "0x05"',
    '"hats": "0x06"',
    '"nonce": 10',
  ])
    assert.ok(Str.includes(fact)(text), fact);
});

test("the site's names are Python constants", () => {
  const text = renderSite(
    { WALLET_ADDRESS_FIELD: "w", DAILY_JOB: "d", DAILY_JOB_TYPE: "t", SAFE_ACCOUNT_PREFIX: "p" },
    literal,
  );
  assert.match(text, /\nWALLET_ADDRESS_FIELD = "w"\n/);
  assert.match(text, /\nSAFE_ACCOUNT_PREFIX = "p"\n/);
});

test("the committed generated files start with their own header", () => {
  for (const [name, output] of Rec.toEntries(OUTPUTS)) {
    const text = readFileSync(`${import.meta.dirname}/../../../${output.path}`, "utf8");
    // JSON has no comments: a generated JSON file says so in its first field, `generated`.
    if (Str.endsWith(".json")(output.path)) {
      assert.equal(Str.split(text, "\n")[1], `  "generated": ${JSON.stringify(generatedFrom(name))},`, output.path);
      continue;
    }
    const comment = Str.endsWith(".py")(output.path) ? "#" : Str.endsWith(".md")(output.path) ? "<!--" : "//";
    assert.equal(firstLine(text), firstLine(header(name, comment)), output.path);
  }
});

test("a package's map has one line per file, in what the file says of itself, grouped by folder", () => {
  const map = renderMap("packages/x", [
    {
      path: "src/things/world/reset.ts",
      text: "// Resetting a world in place. More after.\n// Still the comment.\nimport x;",
    },
    { path: "src/index.ts", text: "// The one import entry: everything another package may import.\nexport {};" },
    { path: "docs/reset.md", text: "# Reset a world in place\n\nBody." },
  ]);
  assert.match(map, /^<!-- Generated by `pnpm generate`/);
  assert.match(
    map,
    /## `src\/things\/world\/`\n\n- \[`reset.ts`\]\(\.\.\/src\/things\/world\/reset.ts\): Resetting a world in place\.\n/,
  );
  assert.match(
    map,
    /- \[`index.ts`\]\(\.\.\/src\/index.ts\): The one import entry: everything another package may import\.\n/,
  );
  assert.match(map, /- \[`reset.md`\]\(\.\.\/docs\/reset.md\): Reset a world in place\n/);
  const headings = Arr.filter(Str.split(map, "\n"), Str.startsWith("## "));
  assert.deepEqual(headings, ["## `docs/`", "## `src/`", "## `src/things/world/`"]);
});

test("what a file says of itself: nothing when it opens with no comment", () => {
  assert.equal(saysOf({ path: "src/a.ts", text: "export const a = 1;\n" }), "");
});
